You are implementing Task 7 of a plan: install Bombadil (Antithesis's browser property-testing tool) and build a static harness page that mounts this project's built dashboard cards with a scripted mock hass.

## Work Directory

Work EXCLUSIVELY in: /Users/raman/projects/lock_code_manager/.worktrees/property-based-testing (git worktree, branch property-based-testing). Node deps already installed (yarn). Never stage `.entire/` files.

## Steps

1. Install Bombadil pinned exact:
```bash
yarn add --dev --exact @antithesishq/bombadil
yarn node_modules/.bin/bombadil --version   # expect a 0.x version; if the binary name/path differs, find it under node_modules/.bin and report
```

2. Build the bundle the harness will load:
```bash
yarn rollup -c
ls -la custom_components/lock_code_manager/www/generated/lock-code-manager.js
```

3. Create `pbt/harness/index.html` with EXACTLY this content:

```html
<!doctype html>
<html>
    <head>
        <meta charset="utf-8" />
        <title>LCM Bombadil Harness</title>
        <style>
            body {
                font-family: sans-serif;
                margin: 16px;
                display: grid;
                grid-template-columns: 1fr 1fr;
                gap: 16px;
            }
            #chaos-panel {
                grid-column: 1 / -1;
                border: 2px dashed #999;
                padding: 8px;
            }
            #chaos-panel button {
                margin: 4px;
                padding: 8px 12px;
            }
        </style>
    </head>
    <body>
        <!-- Chaos levers live in light DOM so Bombadil's click actions reach
             them; each simulates a backend-driven change through the mock
             hass subscription pipeline. -->
        <div id="chaos-panel">
            <button id="chaos-external-pin">External PIN change</button>
            <button id="chaos-toggle-active">Toggle slot active</button>
            <button id="chaos-toggle-enabled">Toggle slot enabled</button>
            <button id="chaos-rename">Rename slot user</button>
            <button id="chaos-toggle-sync">Flip lock sync status</button>
            <button id="chaos-toggle-suspended">Toggle lock suspended</button>
            <button id="chaos-clear-slot">Clear random slot</button>
            <button id="chaos-add-slot">Add lock slot</button>
        </div>
        <div id="masked-zone"></div>
        <div id="lock-codes-zone"></div>
        <script
            type="module"
            src="/custom_components/lock_code_manager/www/generated/lock-code-manager.js"
        ></script>
        <script type="module" src="/pbt/harness/harness.js"></script>
    </body>
</html>
```

4. Create `pbt/harness/harness.js` with EXACTLY this content (adapt ONLY if a runtime error during step 7 verification forces payload-shape corrections — then report every adaptation):

```javascript
/**
 * Bombadil harness: mounts lcm-slot and lcm-lock-codes with a scripted mock
 * hass. Plain JavaScript on purpose — no build step; served statically next
 * to the built bundle. The model below is the single source of truth; chaos
 * buttons mutate it and re-push through the subscription callbacks, the same
 * path the real websocket API uses.
 */

const CONFIG_ENTRY_ID = 'pbt_entry';
const LOCK_ENTITY_ID = 'lock.pbt_front_door';

const model = {
    revision: 0,
    suspended: false,
    slots: {
        1: { active: true, enabled: true, inSync: true, name: 'Alice', pin: '4921' },
        2: { active: false, enabled: false, inSync: true, name: 'Bob', pin: '8375' },
        3: { active: true, enabled: true, inSync: false, name: 'Carol', pin: '6104' }
    }
};

// Read-only window surface for spec extractors. Secret PINs deliberately
// live here (JavaScript only), never in the DOM: the no-leak property greps
// the rendered DOM for them.
window.__lcmHarness = {
    model,
    secretPins: () => Object.values(model.slots).map((slot) => slot.pin)
};

/** Subscriptions keyed by an opaque id -> {message, callback}. */
const subscriptions = new Map();
let nextSubscriptionId = 1;

function slotCardData(slotNum) {
    const slot = model.slots[slotNum];
    return {
        active: slot.active,
        conditions: {},
        config_entry_id: CONFIG_ENTRY_ID,
        config_entry_title: 'PBT Lock Manager',
        enabled: slot.enabled,
        entities: {
            active: `binary_sensor.slot_${slotNum}_active`,
            enabled: `switch.slot_${slotNum}_enabled`,
            name: `text.slot_${slotNum}_name`,
            pin: `text.slot_${slotNum}_pin`
        },
        locks: [
            {
                code: null,
                code_length: slot.pin.length,
                entity_id: LOCK_ENTITY_ID,
                in_sync: slot.inSync,
                name: 'Front Door',
                sync_status: slot.inSync ? 'in_sync' : 'out_of_sync'
            }
        ],
        name: slot.name,
        // Harness cards run code_display: 'masked' — the PIN value never
        // leaves the model; only its length does.
        pin: null,
        pin_length: slot.pin.length,
        slot_num: slotNum
    };
}

function lockCoordinatorData() {
    return {
        lock_entity_id: LOCK_ENTITY_ID,
        lock_name: 'Front Door',
        ...(model.suspended ? { sync_status: 'suspended' } : {}),
        slots: Object.entries(model.slots).map(([slotNum, slot]) => ({
            active: slot.active,
            code: null,
            code_length: slot.pin.length,
            config_entry_id: CONFIG_ENTRY_ID,
            config_entry_title: 'PBT Lock Manager',
            in_sync: slot.inSync,
            is_managed: true,
            name: slot.name,
            slot: Number(slotNum)
        }))
    };
}

function payloadFor(message) {
    if (message.type === 'lock_code_manager/subscribe_code_slot') {
